//! The requests of one file.
//!
//! Every target is first found in the parsed file: by name, or, for an anonymous instance or
//! a name an attribute generates differently than the parser guesses, by the line its
//! declaration starts on. Each target then takes one route:
//!
//! - `alias X := Y` copies the description of `Y`.
//! - A lemma generated by `reassoc` or `elementwise` copies its parent's description and adds
//!   one fixed sentence (see [`crate::assemble`]).
//! - Everything else is described by the model. Declarations an attribute generates
//!   (`to_additive`, `simps`, ...) are asked for in the same request as their parent.
//!
//! Requests follow the file: a run of statements with the scope commands written between
//! them, opened by the scope in effect where the run starts, cut at a token and item budget.
//! Targets that cannot be found go to the per-declaration prompt.

use crate::context::{self, ContextLine};
use crate::estimate_tokens;
use crate::input::{Knowledge, Target};
use crate::scope::{self, Unit, text};
use lean_source::pos::LineIndex;
use lean_source::{Decl, DeclKind, Parsed, Span};
use serde::{Deserialize, Serialize};
use std::collections::{HashMap, HashSet};

/// Limits of one request.
#[derive(Clone, Copy, Debug)]
pub struct Budget {
    /// Estimated tokens of the Lean excerpt.
    pub batch_tokens: usize,
    /// Declarations the model is asked to describe.
    pub batch_items: usize,
    /// Estimated tokens of the dependency descriptions.
    pub context_tokens: usize,
    /// Length at which each dependency description is cut.
    pub description_chars: usize,
}

impl Default for Budget {
    fn default() -> Self {
        Budget {
            batch_tokens: 3000,
            batch_items: 40,
            context_tokens: 1500,
            description_chars: 256,
        }
    }
}

/// A declaration the model is asked to describe.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct Item {
    pub name: String,
    pub kind: String,
    /// How the declaration relates to the excerpt when it is not written there itself.
    pub note: Option<String>,
}

/// A description taken from another declaration instead of the model.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct Route {
    pub name: String,
    /// `alias`, `reassoc` or `elementwise`.
    pub rule: String,
    pub from: String,
}

/// One request to the model.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Batch {
    pub id: String,
    pub path: String,
    pub module: String,
    /// Scope commands and statements, proofs left out, as Lean source.
    pub excerpt: String,
    pub items: Vec<Item>,
    pub context: Vec<ContextLine>,
    /// Dependency descriptions that did not fit the budget.
    pub dropped_context: usize,
    pub estimated_tokens: usize,
}

/// A target left to the per-declaration prompt.
#[derive(Clone, Debug, Serialize, PartialEq, Eq)]
pub struct Unmatched {
    pub name: String,
    pub path: Option<String>,
    pub reason: &'static str,
}

/// Requests, routes and leftovers of one file.
#[derive(Debug, Default)]
pub struct FilePlan {
    pub batches: Vec<Batch>,
    pub routes: Vec<Route>,
    pub unmatched: Vec<Unmatched>,
}

/// Where a target sits in the parsed file.
#[derive(Clone, Copy, Debug)]
struct Placement {
    target: usize,
    top: usize,
    /// The declaration itself, or None for a name an attribute of `top` generates.
    decl: Option<usize>,
}

enum Role {
    Model(Item),
    Route(Route),
}

/// What a classification needs to know about the file.
struct FileView<'a> {
    src: &'a [u8],
    parsed: &'a Parsed,
    /// Target name placed at each declaration.
    names: HashMap<usize, &'a str>,
}

impl FileView<'_> {
    fn name_of(&self, index: usize) -> String {
        self.names
            .get(&index)
            .map(|name| name.to_string())
            .or_else(|| self.parsed.decls[index].name.clone())
            .unwrap_or_else(|| "the declaration it is attached to".to_string())
    }
}

/// Builds the requests of one file.
///
/// # Arguments
/// * `path` - path of the file in its repository, used in request identifiers.
/// * `module` - module name of the file.
/// * `src` - contents of the file.
/// * `targets` - the declarations of this file to describe.
/// * `knowledge` - dependencies and existing descriptions across all files.
/// * `budget` - limits of one request.
pub fn plan_file(
    path: &str,
    module: &str,
    src: &[u8],
    targets: &[&Target],
    knowledge: &Knowledge,
    budget: &Budget,
) -> FilePlan {
    let parsed = lean_source::parse(src);
    let (placements, mut unmatched) = place(&parsed, src, targets, path);
    let view = FileView {
        src,
        parsed: &parsed,
        names: placements
            .iter()
            .filter_map(|p| p.decl.map(|decl| (decl, targets[p.target].name.as_str())))
            .collect(),
    };
    let mut unit_items: HashMap<usize, Vec<Item>> = HashMap::new();
    let mut routes = Vec::new();
    for placement in &placements {
        let name = &targets[placement.target].name;
        match classify(&view, placement, name, knowledge) {
            Role::Model(item) => unit_items.entry(placement.top).or_default().push(item),
            Role::Route(route) => routes.push(route),
        }
    }
    let units = scope::units(src, &parsed, |index| unit_items.contains_key(&index));
    let covered: HashSet<usize> = units.iter().map(|unit| unit.decl).collect();
    for (top, items) in &unit_items {
        if !covered.contains(top) {
            unmatched.extend(items.iter().map(|item| Unmatched {
                name: item.name.clone(),
                path: Some(path.to_string()),
                reason: "declaration outside the command walk",
            }));
        }
    }
    let packed = pack(&units, &mut unit_items, &parsed, src, budget);
    let batches = packed
        .into_iter()
        .enumerate()
        .map(|(index, (excerpt, items))| {
            finish_batch(path, module, index, excerpt, items, knowledge, budget)
        })
        .collect();
    FilePlan {
        batches,
        routes,
        unmatched,
    }
}

/// The Lean source a description of one target is judged against.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct Reference {
    pub name: String,
    pub kind: String,
    pub path: String,
    pub module: String,
    /// Scope commands in effect, outermost first, then any `in` prefixes.
    pub scope: Vec<String>,
    /// The statement written in the source: for a generated name, its parent's.
    pub statement: String,
    /// How a generated or nested name relates to the statement.
    pub note: Option<String>,
}

/// The reference statement of every target that can be found in the file.
pub fn references(path: &str, module: &str, src: &[u8], targets: &[&Target]) -> Vec<Reference> {
    let parsed = lean_source::parse(src);
    let (placements, _) = place(&parsed, src, targets, path);
    let view = FileView {
        src,
        parsed: &parsed,
        names: placements
            .iter()
            .filter_map(|p| p.decl.map(|decl| (decl, targets[p.target].name.as_str())))
            .collect(),
    };
    let tops: HashSet<usize> = placements.iter().map(|p| p.top).collect();
    let units: HashMap<usize, Unit> = scope::units(src, &parsed, |index| tops.contains(&index))
        .into_iter()
        .map(|unit| (unit.decl, unit))
        .collect();
    let mut out = Vec::new();
    for placement in &placements {
        let Some(unit) = units.get(&placement.top) else {
            continue;
        };
        let (kind, note) = match placement.decl {
            Some(index) => {
                let decl = &parsed.decls[index];
                (decl.kind.as_str().to_string(), note(&view, decl))
            }
            None => (
                "generated".to_string(),
                Some(format!(
                    "generated by an attribute of {}",
                    view.name_of(placement.top)
                )),
            ),
        };
        let mut scope = unit.scope.clone();
        scope.extend(unit.prefix.iter().cloned());
        out.push(Reference {
            name: targets[placement.target].name.clone(),
            kind,
            path: path.to_string(),
            module: module.to_string(),
            scope,
            statement: statement(src, &parsed.decls[placement.top]).to_string(),
            note,
        });
    }
    out
}

fn top_of(parsed: &Parsed, mut index: usize) -> usize {
    while let Some(parent) = parsed.decls[index].parent {
        index = parent as usize;
    }
    index
}

/// Finds every target in the file, by name first and then by starting line.
fn place(
    parsed: &Parsed,
    src: &[u8],
    targets: &[&Target],
    path: &str,
) -> (Vec<Placement>, Vec<Unmatched>) {
    let mut by_name: HashMap<&str, usize> = HashMap::new();
    for (index, decl) in parsed.decls.iter().enumerate() {
        if let Some(name) = &decl.name {
            by_name.entry(name.as_str()).or_insert(index);
        }
    }
    let lines = line_ranges(parsed, src);
    let mut claimed = HashSet::new();
    let mut placed: Vec<Option<Placement>> = vec![None; targets.len()];
    for (target, entry) in targets.iter().enumerate() {
        if let Some(&decl) = by_name.get(entry.name.as_str()) {
            claimed.insert(decl);
            let top = top_of(parsed, decl);
            placed[target] = Some(Placement {
                target,
                top,
                decl: Some(decl),
            });
        }
    }
    let mut unmatched = Vec::new();
    for (target, entry) in targets.iter().enumerate() {
        if placed[target].is_some() {
            continue;
        }
        let at_line = entry.start_line.and_then(|line| containing(&lines, line));
        placed[target] = match at_line {
            Some((top, starts_here))
                if starts_here && parsed.decls[top].name.is_none() && claimed.insert(top) =>
            {
                Some(Placement {
                    target,
                    top,
                    decl: Some(top),
                })
            }
            Some((top, _)) => Some(Placement {
                target,
                top,
                decl: None,
            }),
            None => {
                unmatched.push(Unmatched {
                    name: entry.name.clone(),
                    path: Some(path.to_string()),
                    reason: "not found in the source",
                });
                None
            }
        };
    }
    let mut placements: Vec<Placement> = placed.into_iter().flatten().collect();
    placements.sort_by_key(|p| (p.top, p.decl.unwrap_or(usize::MAX), p.target));
    (placements, unmatched)
}

/// First and last line of every top-level declaration that creates a constant, with its
/// index, sorted by first line.
fn line_ranges(parsed: &Parsed, src: &[u8]) -> Vec<(u32, u32, usize)> {
    let index = LineIndex::new(src);
    let mut ranges: Vec<(u32, u32, usize)> = parsed
        .decls
        .iter()
        .enumerate()
        .filter(|(_, decl)| decl.parent.is_none() && !decl.kind.is_virtual())
        .map(|(position, decl)| {
            let first = index.pos(src, decl.range.start).line;
            let last = index.pos(src, decl.range.end.saturating_sub(1)).line;
            (first, last.max(first), position)
        })
        .collect();
    ranges.sort_unstable();
    ranges
}

/// The top-level declaration whose lines contain `line`, and whether it starts there.
///
/// A database range that starts inside a declaration belongs to a name an attribute of that
/// declaration generates: Lean records such a name at the attribute.
fn containing(ranges: &[(u32, u32, usize)], line: u32) -> Option<(usize, bool)> {
    let after = ranges.partition_point(|(first, _, _)| *first <= line);
    let (first, last, index) = *ranges[..after].last()?;
    (line <= last).then_some((index, first == line))
}

/// Decides how a placed target gets its description.
fn classify(view: &FileView, placement: &Placement, name: &str, knowledge: &Knowledge) -> Role {
    let Some(index) = placement.decl else {
        return Role::Model(Item {
            name: name.to_string(),
            kind: "generated".to_string(),
            note: Some(format!(
                "generated by an attribute of {}",
                view.name_of(placement.top)
            )),
        });
    };
    let decl = &view.parsed.decls[index];
    if let Some(route) = derived_route(view, decl, name) {
        return Role::Route(route);
    }
    if decl.parent.is_none()
        && decl.kind == DeclKind::Alias
        && let Some(from) = alias_source(text(view.src, decl.range), name, knowledge)
    {
        return Role::Route(Route {
            name: name.to_string(),
            rule: "alias".to_string(),
            from,
        });
    }
    Role::Model(Item {
        name: name.to_string(),
        kind: decl.kind.as_str().to_string(),
        note: note(view, decl),
    })
}

/// The route of a `reassoc` or `elementwise` lemma whose parent is a target.
fn derived_route(view: &FileView, decl: &Decl, name: &str) -> Option<Route> {
    let origin = text(view.src, decl.origin?);
    let rule = ["reassoc", "elementwise"]
        .into_iter()
        .find(|rule| origin.starts_with(rule))?;
    let parent = decl.parent? as usize;
    let from = view.names.get(&parent)?;
    Some(Route {
        name: name.to_string(),
        rule: rule.to_string(),
        from: from.to_string(),
    })
}

/// How a declaration that is not written on its own relates to the excerpt.
fn note(view: &FileView, decl: &Decl) -> Option<String> {
    let parent = view.name_of(decl.parent? as usize);
    Some(match (decl.generated, decl.origin) {
        (true, Some(origin)) => format!("generated by @[{}] from {parent}", text(view.src, origin)),
        (true, None) => format!("generated by Lean from {parent}"),
        (false, _) => format!("{} of {parent}", decl.kind.as_str().replace('_', " ")),
    })
}

/// The declaration a plain `alias X := Y` points to, if it has a description.
///
/// `Y` is resolved the way Lean would from inside the alias's namespace: `A.B.Y`, then `A.Y`,
/// then `Y`. Aliases of the `alias ⟨mp, mpr⟩ := h` form name one direction of an `iff`, which
/// states something else, and are not copied. The target follows the last `:=`, since an
/// attribute such as `@[deprecated (since := "...")]` may hold one too.
pub fn alias_source(source: &str, name: &str, knowledge: &Knowledge) -> Option<String> {
    let (written, value) = source.rsplit_once(":=")?;
    let value = value.trim();
    if value.is_empty() || value.contains(char::is_whitespace) || written.contains('⟨') {
        return None;
    }
    let identifier = value.trim_start_matches("_root_.");
    let mut namespace = name.rsplit_once('.').map_or("", |(prefix, _)| prefix);
    loop {
        let candidate = if namespace.is_empty() {
            identifier.to_string()
        } else {
            format!("{namespace}.{identifier}")
        };
        if candidate != name && knowledge.is_described(&candidate) {
            return Some(candidate);
        }
        if namespace.is_empty() {
            return None;
        }
        namespace = namespace.rsplit_once('.').map_or("", |(prefix, _)| prefix);
    }
}

/// The statement of a declaration: the signature of a theorem, everything of the rest.
pub fn statement<'a>(src: &'a [u8], decl: &Decl) -> &'a str {
    let end = match decl.kind {
        DeclKind::Theorem | DeclKind::Lemma => decl.signature.end,
        _ => decl.range.end,
    };
    text(src, Span::new(decl.range.start, end)).trim_end()
}

struct Open {
    parts: Vec<String>,
    items: Vec<Item>,
    tokens: usize,
}

/// Groups units into requests, each an excerpt with the items it asks for.
fn pack(
    units: &[Unit],
    unit_items: &mut HashMap<usize, Vec<Item>>,
    parsed: &Parsed,
    src: &[u8],
    budget: &Budget,
) -> Vec<(String, Vec<Item>)> {
    let mut out = Vec::new();
    let mut current: Option<Open> = None;
    let mut carry: Vec<String> = Vec::new();
    for unit in units {
        let items = unit_items.remove(&unit.decl).unwrap_or_default();
        let statement = statement(src, &parsed.decls[unit.decl]);
        let mut continued: Vec<String> = std::mem::take(&mut carry);
        continued.extend(unit.between.iter().cloned());
        continued.push(statement.to_string());
        let addition = continued.join("\n");
        let tokens = estimate_tokens(&addition);
        match current.as_mut() {
            Some(open)
                if open.tokens + tokens <= budget.batch_tokens
                    && open.items.len() + items.len() <= budget.batch_items =>
            {
                open.parts.push(addition);
                open.items.extend(items);
                open.tokens += tokens;
            }
            _ => {
                if let Some(open) = current.take() {
                    out.push((open.parts.join("\n\n"), open.items));
                }
                let mut opening = unit.scope.clone();
                opening.extend(unit.prefix.iter().cloned());
                opening.push(statement.to_string());
                let opening = opening.join("\n");
                current = Some(Open {
                    tokens: estimate_tokens(&opening),
                    parts: vec![opening],
                    items,
                });
            }
        }
    }
    if let Some(open) = current {
        out.push((open.parts.join("\n\n"), open.items));
    }
    out
}

fn finish_batch(
    path: &str,
    module: &str,
    index: usize,
    excerpt: String,
    items: Vec<Item>,
    knowledge: &Knowledge,
    budget: &Budget,
) -> Batch {
    let names: Vec<String> = items.iter().map(|item| item.name.clone()).collect();
    let selection = context::select(
        &names,
        knowledge,
        budget.context_tokens,
        budget.description_chars,
    );
    let context_tokens: usize = selection
        .lines
        .iter()
        .map(|line| estimate_tokens(&context::render(line)))
        .sum();
    Batch {
        id: format!("{path}#{index}"),
        path: path.to_string(),
        module: module.to_string(),
        estimated_tokens: estimate_tokens(&excerpt) + context_tokens,
        excerpt,
        items,
        context: selection.lines,
        dropped_context: selection.dropped,
    }
}
